import type {
  ArcangelRequest,
  ArcangelResponse,
} from "@arcangel/framework/http"
import { deleteServiceZonesWorkflow } from "@arcangel/arcangel/core-flows"

export async function POST(
  req: ArcangelRequest,
  res: ArcangelResponse
) {
  const { result } = await deleteServiceZonesWorkflow(req.scope)
    .run({
      input: {
        ids: ["serzo_123"]
      }
    })

  res.send(result)
}

